private const string MODULE_MARK_HTML_TEMPLATE = "BangDiemModun.htm";
private const string MODULE_MARK_EXCEL_TEMPLATE = "BangDiemModun.xls";
private const string MODULE_MARK_TD_BORDER = "border:1px solid #000000;padding:4px;vertical-align:middle;";

private void SetExportModuleMarkEnabled(bool bolEnabled)
{
    mnuItemExportModuleMark.Enabled = bolEnabled;
    mnuItemExportModuleMarkExcel.Enabled = bolEnabled;
}

private void mnuItemExportModuleMark_Click(object sender, EventArgs e)
{
    ExportModuleMarkToHTML();
}

private void mnuItemExportModuleMarkExcel_Click(object sender, EventArgs e)
{
    ExportModuleMarkToExcel();
}

private void ExportModuleMarkToHTML()
{
    ExportModuleMark(false);
}

private void ExportModuleMarkToExcel()
{
    ExportModuleMark(true);
}

private void ExportModuleMark(bool bolToExcel)
{
    if (dtbData == null || dtbClassSubject == null || dtbClassSubject.Rows.Count == 0)
    {
        MessageManager.Warning("Không có dữ liệu để xuất!");
        return;
    }

    string strHead = ModuleMarkHeaderToHTML(!bolToExcel);
    string strBody = ModuleMarkBodyToHTML(!bolToExcel);
    string strDetail = "<table cellpadding='4' cellspacing='0' style='border-collapse:collapse; font-family:Times New Roman; font-size:12pt;'>"
        + strHead + strBody + "</table>";

    string strFileContent = bolToExcel ? GetModuleMarkExcelTemplate() : GetModuleMarkHTMLTemplate();
    strFileContent = strFileContent.Replace("{DETAIL}", strDetail);

    string strClassCode = uClass.ClassIDEditValue.ToString();
    foreach (char chrInvalid in System.IO.Path.GetInvalidFileNameChars())
        strClassCode = strClassCode.Replace(chrInvalid, '_');

    string strTemplateName = bolToExcel ? MODULE_MARK_EXCEL_TEMPLATE : MODULE_MARK_HTML_TEMPLATE;
    string strFileNameAs = String.Format("{0}_{1}_{2}",
        strClassCode,
        DateTime.Now.ToString("HHmmss"),
        strTemplateName);
    Libs.Files.WriteFile(strFileNameAs, strFileContent);
    System.Diagnostics.Process.Start(strFileNameAs);
}

