private string ModuleMarkFormatValue(object objValue, bool bolForHtml)
{
    if (objValue == null || objValue == DBNull.Value || objValue.ToString().Trim() == "")
        return bolForHtml ? "&nbsp;" : "";

    string strValue = objValue.ToString().Trim();
    if (strValue == "-1" || strValue == "-1.0" || strValue == "-1,0")
        return "R";
    if (strValue == "-2" || strValue == "-2.0" || strValue == "-2,0")
        return "P";
    return strValue;
}

private bool ModuleMarkIsFailed(object objValue)
{
    string strValue = ModuleMarkFormatValue(objValue, false);
    if (strValue == "" || strValue == "P" || strValue == "R")
        return false;

    double dblMark = 0;
    if (!double.TryParse(strValue, out dblMark))
        return false;
    return dblMark < 5;
}

