private string ModuleMarkBodyToHTML()
{
    StringBuilder sb = new StringBuilder();
    int intSTT = 0;

    for (int i = 0; i < gvData.RowCount; i++)
    {
        DataRow drw = gvData.GetDataRow(i);
        if (drw == null)
            continue;

        intSTT++;
        sb.Append("<tr>");
        sb.Append("<td style='" + MODULE_MARK_TD_BORDER + "text-align:center;'>" + intSTT.ToString() + "</td>");

        string strFullName = (drw["StudentFirstName"].ToString() + " " + drw["StudentLastName"].ToString()).Trim();
        sb.Append("<td class='cell-name' style='" + MODULE_MARK_TD_BORDER + "text-align:left;white-space:nowrap;'>" + strFullName + "</td>");

        StringBuilder sbRetake = new StringBuilder();
        for (int j = 0; j < dtbClassSubject.Rows.Count; j++)
        {
            int intIndex = j + 1;
            string strField = "FinalSummary_" + intIndex.ToString();
            object objValue = drw[strField];
            string strValue = ModuleMarkFormatValue(objValue);
            string strStyle = " style='" + MODULE_MARK_TD_BORDER + "text-align:center;'";

            if (ModuleMarkIsFailed(objValue))
            {
                strStyle = " style='" + MODULE_MARK_TD_BORDER + "background-color:Yellow;text-align:center;'";
                if (sbRetake.Length > 0)
                    sbRetake.Append(", ");
                sbRetake.Append(dtbClassSubject.Rows[j]["SubjectName"].ToString());
            }

            sb.Append("<td" + strStyle + ">" + strValue + "</td>");
        }

        string strRetake = sbRetake.Length > 0 ? sbRetake.ToString() : "&nbsp;";
        sb.Append("<td style='" + MODULE_MARK_TD_BORDER + "text-align:left;'>" + strRetake + "</td>");
        sb.Append("</tr>\r\n");
    }

    return sb.ToString();
}

